### 1. Kernel Modifications (xv6-riscv)

These changes provide the low-level hooks necessary for user-level tools to inspect the disk directly.

#### A. `kernel/fs.h`
Add the `inode_info` structure to facilitate passing metadata to user space.
```c
struct inode_info {
  uint type;
  short major;
  short minor;
  short nlink;
  uint size;
  uint addrs[13];
};
```

#### B. `kernel/sysfile.c`
Implement `sys_get_dinode` to read raw disk inodes.
```c
#include "fs.h"
#include "buf.h"

uint64
sys_get_dinode(void)
{
  int inum;
  uint64 addr; 
  struct buf *bp;
  struct dinode *dip;
  struct superblock sb;

  if(argint(0, &inum) < 0 || argaddr(1, &addr) < 0)
    return -1;

  // Read superblock to find inode layout
  bp = bread(1, 1);
  memmove(&sb, bp->data, sizeof(sb));
  brelse(bp);

  if(inum < 0 || inum >= sb.ninodes) return -1;

  bp = bread(1, IBLOCK(inum, sb));
  dip = (struct dinode*)bp->data + (inum % IPB);

  struct inode_info info;
  info.type = dip->type;
  info.nlink = dip->nlink;
  info.size = dip->size;
  memmove(info.addrs, dip->addrs, sizeof(info.addrs));
  brelse(bp);

  if(copyout(myproc()->pagetable, addr, (char *)&info, sizeof(info)) < 0)
    return -1;
  return 0;
}
```

#### C. Plumbing
*   **`kernel/syscall.h`**: `#define SYS_get_dinode 22`
