#### `user/directoryWalker.c`
```c
#include "kernel/types.h"
#include "kernel/fs.h"
#include "kernel/stat.h"
#include "user/user.h"

void walk(char *path) {
  int fd;
  struct dirent de;
  struct stat st;
  struct inode_info info;

  if((fd = open(path, 0)) < 0) return;
  if(fstat(fd, &st) < 0 || st.type != T_DIR) {
    close(fd);
    return;
  }

  char buf[512];
  while(read(fd, &de, sizeof(de)) == sizeof(de)) {
    if(de.inum == 0 || strcmp(de.name, ".") == 0 || strcmp(de.name, "..") == 0)
      continue;

    printf("Path: %s/%s | Inode: %d | ", path, de.name, de.inum);
    if(get_dinode(de.inum, &info) == 0) {
        printf("Type: %d | Size: %d\n", info.type, info.size);
    }

    if(info.type == T_DIR) {
      strcpy(buf, path);
      strcat(buf, "/");
      strcat(buf, de.name);
      walk(buf);
    }
  }
  close(fd);
}

int main(int argc, char *argv[]) {
  char *start = (argc < 2) ? "." : argv[1];
  walk(start);
  exit(0);
}
```

