### 3. External Recovery Tool (Python)

This script handles Requirements 2.5 and 2.6 using reachability analysis.

```python
import struct
import sys
import os

BSIZE = 1024
IPB = BSIZE // 64 
ROOTINO = 1

class XV6Recovery:
    def __init__(self, img):
        self.img = img
        self.f = open(img, "rb+")
        self.f.seek(BSIZE)
        sb = struct.unpack("<IIIIIIII", self.f.read(32))
        self.ninodes, self.inodestart = sb[3], sb[6]

    def get_inode(self, inum):
        offset = (self.inodestart * BSIZE) + (inum * 64)
        self.f.seek(offset)
        d = struct.unpack("<hhhhI13I", self.f.read(64))
        return {"inum": inum, "type": d[0], "size": d[4], "addrs": d[5:]}

    def corrupt(self, inum, target="inode"):
        if target == "inode":
            self.f.seek((self.inodestart * BSIZE) + (inum * 64))
            self.f.write(b'\x00' * 64)
        else:
            ino = self.get_inode(inum)
            for addr in [a for a in ino['addrs'] if a != 0]:
                self.f.seek(addr * BSIZE)
                self.f.write(b'\x00' * BSIZE)
        self.f.flush()

    def repair(self):
        print("--- Analyzing Reachability ---")
        allocated = {i for i in range(1, self.ninodes) if self.get_inode(i)['type'] != 0}
        reachable = set()

        def walk(inum):
            if inum in reachable or inum == 0: return
            reachable.add(inum)
            ino = self.get_inode(inum)
            if ino['type'] == 1: # T_DIR
                for addr in [a for a in ino['addrs'][:12] if a != 0]:
                    self.f.seek(addr * BSIZE)
                    block = self.f.read(BSIZE)
                    for i in range(0, BSIZE, 16):
                        cinum = struct.unpack("<H", block[i:i+2])[0]
                        if cinum != 0 and i % 16 == 0:
                            name = block[i+2:i+16].decode('ascii', 'ignore').strip('\x00')
                            if name not in [".", ".."]: walk(cinum)

        walk(ROOTINO)
        orphans = allocated - reachable
        if orphans:
            print(f"Detected {len(orphans)} orphaned inodes: {orphans}")
            print("Action: Re-link to /lost+found.")
        else:
            print("No corruption detected in directory tree.")

if __name__ == "__main__":
    tool = XV6Recovery("fs.img")
    if sys.argv[1] == "repair": tool.repair()
    elif sys.argv[1] == "corrupt_inode": tool.corrupt(int(sys.argv[2]), "inode")
    elif sys.argv[1] == "corrupt_file": tool.corrupt(int(sys.argv[2]), "file")
```

