function drawHexBin(canvasId, pData, color) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const center = 70;
    const radius = 55;
    const sides = 6;

    // Normalize stats to a 0.0 - 1.0 scale for the radar chart
    const values = [
        pData.score / 10,           // Score (Max 10)
        pData.hp / 100,             // HP (Max 100)
        pData.hits / 20,            // Successful Hits
        pData.items / 5,            // Power-ups collected
        pData.oppHits / 10,         // Hits on opponent
        0.7                         // Consistency factor
    ];

    ctx.clearRect(0, 0, 140, 140);

    // Draw Background Grid
    ctx.strokeStyle = '#333';
    ctx.beginPath();
    for(let i=0; i<sides; i++) {
        let x = center + radius * Math.cos(i * 2 * Math.PI / sides);
        let y = center + radius * Math.sin(i * 2 * Math.PI / sides);
        ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.stroke();

    // Draw Dynamic Data Shape
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.5;
    ctx.beginPath();
    for(let i=0; i<sides; i++) {
        let val = Math.min(values[i], 1.0); 
        let x = center + (radius * val) * Math.cos(i * 2 * Math.PI / sides);
        let y = center + (radius * val) * Math.sin(i * 2 * Math.PI / sides);
        ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = color;
    ctx.globalAlpha = 1;
    ctx.stroke();
}

